package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Random;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class RandomStringUtils_random_TriageGen0Test {

    @Test
    public void testRandom_CountZero() {
        String result = RandomStringUtils.random(0, 0, 0, true, true, null, new Random());
        assertEquals("", result);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testRandom_CountNegative() {
        RandomStringUtils.random(-1, 0, 0, true, true, null, new Random());
    }

    @Test(expected = IllegalArgumentException.class)
    public void testRandom_EmptyCharsArray() {
        RandomStringUtils.random(5, 0, 0, true, true, new char[]{}, new Random());
    }

    @Test
    public void testRandom_WithCharsArrayAndStartEndZero() {
        char[] chars = {'a', 'b', 'c'};
        // When chars != null and start/end == 0, end becomes chars.length
        // gap = 3 - 0 = 3. random.nextInt(3) + 0 -> indices 0, 1, 2
        String result = RandomStringUtils.random(5, 0, 0, false, false, chars, new Random());
        assertEquals(5, result.length());
        for (char c : result.toCharArray()) {
            assertTrue(c == 'a' || c == 'b' || c == 'c');
        }
    }

    @Test
    public void testRandom_NoLettersNoNumbersAndStartEndZero() {
        // !letters && !numbers -> end = Integer.MAX_VALUE, start = 0
        // This goes into the branch where ch = (char) (random.nextInt(gap) + start)
        // We use a small count to avoid infinite loops or memory issues if random hits non-printable
        String result = RandomStringUtils.random(5, 0, 0, false, false, null, new Random());
        assertEquals(5, result.length());
    }

    @Test
    public void testRandom_LettersOrNumbersAndStartEndZero() {
        // letters || numbers -> end = 'z' + 1, start = ' '
        String result = RandomStringUtils.random(5, 0, 0, true, false, null, new Random());
        assertEquals(5, result.length());
        for (char c : result.toCharArray()) {
            assertTrue(Character.isLetter(c));
        }
    }

    @Test
    public void testRandom_SpecificRangeWithChars() {
        char[] chars = {'A', 'B', 'C', 'D'};
        // start=1, end=3 -> gap=2. random.nextInt(2) + 1 -> indices 1, 2 ('B', 'C')
        String result = RandomStringUtils.random(10, 1, 3, false, false, chars, new Random());
        assertEquals(10, result.length());
        for (char c : result.toCharArray()) {
            assertTrue(c == 'B' || c == 'C');
        }
    }

    @Test
    public void testRandom_SurrogateHandling() {
        // To trigger surrogate branches, we need to provide chars that include surrogates
        // High surrogate: 55296 - 56191
        // Private high surrogate: 56192 - 56319 (should be skipped)
        // Low surrogate: 56320 - 57343

        char[] specialChars = {
            (char) 55296, // High surrogate
            (char) 56192, // Private high surrogate (skip)
            (char) 56320, // Low surrogate
            'A'           // Normal letter
        };

        // We use a seed or a controlled Random to ensure we hit the branches if possible,
        // but since we want coverage, we just need to hit them once.
        // Using a high count to increase probability of hitting all branches.
        String result = RandomStringUtils.random(100, 0, 4, true, false, specialChars, new Random());

        // The length might not be 100 because of the 'skip' branch and surrogate insertion
        // But the logic should not crash.
        assertNotNull(result);
    }

    @Test
    public void testRandom_FilterLogic() {
        // Test that when letters=true and numbers=false, numbers are skipped
        char[] mixed = {'a', '1', 'b', '2'};
        // start=0, end=4, gap=4. indices 0-3.
        // Since we want to ensure '1' and '2' are skipped, we might need to loop 
        // or use a specific Random if it were mockable. 
        // With standard Random, we just check if the output is valid.
        String result = RandomStringUtils.random(10, 0, 4, true, false, mixed, new Random());

        for (char c : result.toCharArray()) {
            assertTrue("Character " + c + " should be a letter", Character.isLetter(c));
        }
    }

    @Test
    public void testRandom_SurrogateCountAdjustment() {
        // Testing the count++ logic when a character is skipped or surrogates are added
        // We force the 'skip' branch (56192 - 56319)
        char[] skipChar = {(char) 56200, 'A'};
        // We need to ensure the loop eventually finishes.
        // Since we use a real Random, we just run it.
        String result = RandomStringUtils.random(10, 0, 2, true, false, skipChar, new Random());
        assertNotNull(result);
    }
}
